204	    it('receives user message after any beforeUserInput modification', async () => {
205	      let afterReceived = '';
206	      const hooks: OrchestratorHooks = {
207	        beforeUserInput: async (_s, _msg) => 'modified',
208	        afterUserInput: async (_s, msg) => {
209	          afterReceived = msg;
210	        },
211	      };
212	
213	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
214	      await orchestrator.processMessage(createSession('original'));
215	
216	      expect(afterReceived).toBe('modified');
217	    });
218	  });
219	
220	  describe('beforeModelResponse', () => {
221	    it('replaces system prompt with returned value', async () => {
222	      const {provider, sent} = capturingProvider();
223	
224	      const hooks: OrchestratorHooks = {
225	        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
226	      };
227	
228	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
229	      await orchestrator.processMessage(createSession('hello'));
230	
231	      expect(sent.systemPrompt).toBe('Custom prompt for this question');
232	    });
233	  });
234	
235	  describe('afterModelResponse', () => {
236	    it('receives collected response text and usage', async () => {
237	      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
238	      let receivedText = '';
239	      let receivedUsage: UsageMetadata | undefined;
240	
241	      const hooks: OrchestratorHooks = {
242	        afterModelResponse: async (_session, text, u) => {
243	          receivedText = text;
